static void testConcurrentAutomationRefreshMailbox(){
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);for(int n=0;n<1000;++n){st_engine_note_on(e,0,0,60+n%12,100);st_engine_note_off(e,0,60+n%12);}for(int n=0;n<100000;++n)st_engine_refresh_automation(e);Audio a(64);render(e,a);STEvent event;int on=0,off=0,parameters=0;while(st_engine_pop_event(e,&event)){on+=event.type==ST_EVENT_NOTE_ON;off+=event.type==ST_EVENT_NOTE_OFF;parameters+=event.type==ST_EVENT_PARAMETER;}assert(on==1000&&off==1000&&parameters==24);auto status=st_engine_status(e);assert(status.droppedCommands==0&&status.droppedEvents==0);}
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);Audio initial(64);render(e,initial);STEvent event;while(st_engine_pop_event(e,&event)){}std::atomic<bool>go{false},notesDone{false},refreshDone{false};int on=0,off=0;std::thread audio([&]{while(!go.load(std::memory_order_acquire))std::this_thread::yield();Audio a(32);auto tick=[&]{render(e,a);STEvent value;while(st_engine_pop_event(e,&value)){on+=value.type==ST_EVENT_NOTE_ON;off+=value.type==ST_EVENT_NOTE_OFF;}};while(!notesDone.load(std::memory_order_acquire)||!refreshDone.load(std::memory_order_acquire))tick();tick();});std::thread ui([&]{while(!go.load(std::memory_order_acquire))std::this_thread::yield();for(int n=0;n<1000;++n){st_engine_note_on(e,0,0,48+n%24,100);st_engine_note_off(e,0,48+n%24);}notesDone.store(true,std::memory_order_release);});std::thread refresh([&]{while(!go.load(std::memory_order_acquire))std::this_thread::yield();for(int n=0;n<100000;++n)st_engine_refresh_automation(e);refreshDone.store(true,std::memory_order_release);});go.store(true,std::memory_order_release);ui.join();refresh.join();audio.join();assert(on==1000&&off==1000);auto status=st_engine_status(e);assert(status.droppedCommands==0&&status.droppedEvents==0);}
}
