static void configureCheckpointMusic(STEngine*e){configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);st_engine_set_timing(e,123,4,.2f,.7f);st_engine_set_pattern(e,0,4);st_engine_set_pattern(e,1,3);int32_t sequence[]={0,1};st_engine_set_sequence(e,sequence,2,0,1);for(int p=0;p<2;++p)for(int r=0;r<(p?3:4);++r){auto step=st_default_step();step.note=60+p*12+r;step.gate=8;st_engine_set_step(e,p,0,r,step,nullptr,0);}st_engine_add_automation_point(e,1,0,ST_TARGET_VOLUME,0,0,1,0,.25);st_engine_add_automation_point(e,1,0,ST_TARGET_VOLUME,0,0,1,2,.75);st_engine_commit_update(e);}
static STTransportState captureTransport(STEngine*e){realtime=true;auto state=st_engine_capture_transport(e);realtime=false;return state;}
static void restoreTransport(STEngine*e,STTransportState state,int resume){realtime=true;st_engine_restore_transport(e,state,resume);realtime=false;}
static void temporaryExport(STEngine*e){st_engine_seek(e,0,0,0);st_engine_play(e,1);Audio a(2048);render(e,a);st_engine_stop(e);render(e,a);st_engine_panic(e);st_engine_seek(e,0,0,0);}
static void testTransportCheckpoint(){
    // Untouched/seeked zero-frame cursors must not jump forward a row.
    {Engine e;configureCheckpointMusic(e);auto initial=captureTransport(e);assert(!initial.playing&&!initial.songMode&&st_engine_status(e).position==0&&initial.transportFrames==0);st_engine_seek(e,1,2,1);st_engine_render(e,nullptr,nullptr,0);auto status=st_engine_status(e);assert(status.position==2&&status.row==2&&!status.playing);auto stopped=captureTransport(e);temporaryExport(e);restoreTransport(e,stopped,1);STEvent event;assert(!st_engine_pop_event(e,&event));auto after=st_engine_status(e);assert(after.position==status.position&&after.seconds==status.seconds&&!after.playing&&after.songMode==status.songMode);assert(noteEvents(renderEvents(e,1000)).empty());assert(st_engine_status(e).seconds==status.seconds);}
    for(int mode:{0,1}){Engine e;configureCheckpointMusic(e);st_engine_seek(e,1,1,1);st_engine_play(e,mode);Audio before(1379);render(e,before);auto status=st_engine_status(e);auto saved=captureTransport(e);assert(saved.playing&&saved.songMode==mode&&saved.rowHasStarted&&saved.rowRemaining>0&&status.position>1&&status.position<2);temporaryExport(e);restoreTransport(e,saved,1);auto restored=st_engine_status(e);assert(restored.playing&&restored.songMode==mode&&restored.pattern==status.pattern&&restored.row==status.row&&restored.sequence==status.sequence&&restored.seconds==status.seconds&&restored.position==status.position);auto exact=captureTransport(e);assert(exact.rowRemaining==saved.rowRemaining&&exact.rowDuration==saved.rowDuration&&exact.transportFrames==saved.transportFrames);STEvent event;assert(!st_engine_pop_event(e,&event));auto events=renderEvents(e,size_t(std::ceil(saved.rowRemaining))+2,127);auto notes=noteEvents(events);assert(notes.size()==1&&notes[0].e.type==ST_EVENT_NOTE_ON&&notes[0].e.note==74&&notes[0].frame==uint64_t(std::ceil(saved.rowRemaining)));auto parameters=parameterChanges(events,ST_TARGET_VOLUME);assert(!parameters.empty()&&parameters[0].frame==0&&parameters[0].e.value==.25);}
    // A Stop queued just before capture is observed without rendering a sample.
    {Engine e;configureCheckpointMusic(e);st_engine_play(e,1);Audio warm(2000);render(e,warm);double seconds=st_engine_status(e).seconds;st_engine_stop(e);auto stopped=captureTransport(e);assert(!stopped.playing&&stopped.transportFrames==2000&&st_engine_status(e).seconds==seconds);temporaryExport(e);restoreTransport(e,stopped,1);assert(!st_engine_status(e).playing&&st_engine_status(e).seconds==seconds);assert(noteEvents(renderEvents(e,1000)).empty());}
    // User cancellation wins, although temporary export Stop is normally ignored.
    {Engine e;configureCheckpointMusic(e);st_engine_play(e,0);Audio warm(321);render(e,warm);auto saved=captureTransport(e);temporaryExport(e);st_engine_stop(e);restoreTransport(e,saved,0);assert(!st_engine_status(e).playing&&st_engine_status(e).seconds==321.0/48000);STEvent event;assert(!st_engine_pop_event(e,&event));assert(noteEvents(renderEvents(e,1000)).empty());}
    // Pattern mode still wraps its active pattern rather than entering Song mode.
    {Engine e;configureCheckpointMusic(e);st_engine_seek(e,1,2,1);st_engine_play(e,0);Audio warm(500);render(e,warm);auto saved=captureTransport(e);temporaryExport(e);restoreTransport(e,saved,1);auto notes=noteEvents(renderEvents(e,size_t(std::ceil(saved.rowRemaining))+2));assert(notes.size()==1&&notes[0].e.note==72&&notes[0].frame==uint64_t(std::ceil(saved.rowRemaining)));assert(!st_engine_status(e).songMode&&st_engine_status(e).pattern==1&&st_engine_status(e).row==0);}
    // Timeline audio can outlive the sequence; its absolute source cursor survives.
    {Engine e;configure(e);std::vector<float>sample(48000,.2f);st_engine_begin_update(e);st_engine_set_pattern(e,0,1);st_engine_set_audio_asset(e,0,sample.data(),nullptr,sample.size(),48000);st_engine_add_audio_clip(e,0,0,0,2,0,1,0,0,0);st_engine_commit_update(e);st_engine_play(e,1);Audio warm(10000);render(e,warm);auto saved=captureTransport(e);assert(saved.sequenceFinished&&saved.transportFrames==10000);temporaryExport(e);restoreTransport(e,saved,1);Audio tail(38001);render(e,tail);assert(tail.energy(0,37999)>.001&&tail.l[38000]==0&&!st_engine_status(e).playing);}
    // Public checkpoint fields are sanitized, and no temporary voice survives.
    {Engine e;configure(e);auto state=captureTransport(e);st_engine_note_on(e,0,0,60,100);Audio warm(128);render(e,warm);state.pattern=999999;state.row=-10;state.sequence=999999;state.rowDuration=NAN;state.rowRemaining=INFINITY;state.transportFrames=NAN;restoreTransport(e,state,0);auto status=st_engine_status(e);assert(status.pattern==0&&status.row==0&&status.sequence==0&&std::isfinite(status.position)&&status.seconds==0);Audio quiet(128);render(e,quiet);assert(quiet.energy()==0);}
    // Mid-beat restore stays silent until the next metronome beat; a checkpoint
    // immediately before a beat still clicks at its original sample boundary.
    for(size_t at:{size_t(12345),size_t(24000)}){Engine e;configure(e);st_engine_begin_update(e);st_engine_set_metronome(e,1,4,4,.3f);st_engine_commit_update(e);st_engine_play(e,0);Audio warm(at);render(e,warm);auto state=captureTransport(e);temporaryExport(e);restoreTransport(e,state,1);size_t nextBeat=at==24000?0:24000-at;Audio after(nextBeat+512);render(e,after);if(nextBeat)assert(after.energy(0,nextBeat)==0);assert(after.energy(nextBeat,nextBeat+512)>.0001);}
}
static void configureHostMixVoice(STEngine*e,bool raw){configure(e);st_engine_begin_update(e);st_engine_set_host_mixing(e,raw,0xffff);st_engine_set_timing(e,120,4,0,raw?0:1);auto track=st_default_track();track.volume=raw?0:1;track.pan=raw?1:0;track.mute=raw;track.delaySend=track.reverbSend=raw?1:0;st_engine_set_track(e,0,track);track=st_default_track();track.solo=raw;st_engine_set_track(e,1,track);auto p=modulationInstrument();loadTestTone(e,0,TEST_SAW);p.pan=-.3f;p.drive=.1f;p.cutoff=1200;p.filterEnvAmount=24;p.filterDecay=.05f;p.lfoRate=2;p.lfoDepth=.1f;st_engine_set_instrument(e,0,p);st_engine_commit_update(e);st_engine_note_on(e,0,0,69,100);}
static void testRawHostMixing(){
    // Host strips receive full instrument DSP despite track fader/mute/solo/master.
    {Engine raw,reference;configureHostMixVoice(raw,true);configureHostMixVoice(reference,false);Audio actual(8192),expected(8192),returns(8192);busRender(raw,0,0,actual);busRender(reference,0,0,expected);busRender(raw,16,0,returns);assert(actual.l==expected.l&&actual.r==expected.r&&actual.energy()>.001&&returns.energy()==0);}
    // Explicitly disabled host mixing ignores its mask and keeps legacy PCM exact.
    {Engine a,b;configure(a);configure(b);st_engine_begin_update(b);st_engine_set_host_mixing(b,0,0);st_engine_commit_update(b);st_engine_note_on(a,0,0,69,100);st_engine_note_on(b,0,0,69,100);Audio first(4096),second(4096);render(a,first);render(b,second);assert(first.l==second.l&&first.r==second.r);}
    // A raw computational exclusion does not freeze a native voice's envelopes/LFO.
    {Engine raw,reference;configureHostMixVoice(raw,true);configureHostMixVoice(reference,true);Audio a(512),b(512);render(raw,a);render(reference,b);st_engine_begin_update(raw);st_engine_set_host_mixing(raw,1,0);st_engine_commit_update(raw);render(raw,a);render(reference,b);assert(a.energy()==0);st_engine_begin_update(raw);st_engine_set_host_mixing(raw,1,1);st_engine_commit_update(raw);render(raw,a);render(reference,b);assert(a.l==b.l&&a.r==b.r);}
    // Unscaled metronome lives only on bus16, even when the raw master is zero.
    {Engine raw,reference;for(auto*e:{raw.e,reference.e}){configure(e);st_engine_begin_update(e);st_engine_set_timing(e,120,4,0,e==raw.e?0:1);st_engine_set_host_mixing(e,e==raw.e,0);st_engine_set_metronome(e,1,4,4,.3f);st_engine_commit_update(e);st_engine_play(e,0);}Audio a(512),b(512);busRender(raw,16,0,a);busRender(reference,16,0,b);assert(a.l==b.l&&a.r==b.r&&a.energy()>.001);}
    // Switching away and back cannot resurrect an old legacy delay tail.
    {Engine e;configure(e,ST_INSTRUMENT_SAMPLE);float sample[]={.5f};st_engine_begin_update(e);st_engine_set_sample(e,0,sample,nullptr,1,48000);auto track=st_default_track();track.delaySend=1;st_engine_set_track(e,0,track);st_engine_set_effects(e,.01f,.8f,1,.7f,.4f,0);st_engine_commit_update(e);st_engine_note_on(e,0,0,60,127);Audio head(512);render(e,head);assert(head.energy(480,512)>.00001);st_engine_begin_update(e);st_engine_set_host_mixing(e,1,0xffff);st_engine_commit_update(e);Audio quiet(128);render(e,quiet);assert(quiet.energy()==0);st_engine_begin_update(e);st_engine_set_host_mixing(e,0,0);st_engine_commit_update(e);Audio tail(2048);render(e,tail);assert(tail.energy()==0);}
    // Timeline clips retain gain/source timing but bypass track mute/master scaling.
    {Engine e;configure(e);std::vector<float>sample(48000,.2f);st_engine_begin_update(e);st_engine_set_audio_asset(e,0,sample.data(),nullptr,sample.size(),48000);st_engine_add_audio_clip(e,0,0,0,2,0,.5f,0,0,0);auto track=st_default_track();track.volume=0;track.mute=1;st_engine_set_track(e,0,track);st_engine_set_timing(e,120,4,0,0);st_engine_set_host_mixing(e,1,1);st_engine_commit_update(e);st_engine_play(e,1);Audio a(512);render(e,a);for(float value:a.l)assert(std::abs(value-.1f)<1e-7);st_engine_begin_update(e);st_engine_set_host_mixing(e,1,0);st_engine_commit_update(e);render(e,a);assert(a.energy()==0);}
}
