static std::vector<Timed> hostEvents(std::vector<Timed>events){events.erase(std::remove_if(events.begin(),events.end(),[](const Timed&e){return e.e.type!=ST_EVENT_HOST_PARAMETER;}),events.end());return events;}
/* Host events carry the destination map of the project that emitted them, so a host
   whose destination table changed before this project was republished can drop them;
   republishing re-sends every host lane (also an unchanged step lane). */
static void testHostAutomationMap(){
    Engine e;configure(e);st_engine_begin_update(e);st_engine_set_host_automation_map(e,0x51);st_engine_add_host_automation_point(e,0,3,7,1,0,0.25);st_engine_add_automation_point(e,0,0,ST_TARGET_VOLUME,0,0,1,0,0.5);st_engine_commit_update(e);st_engine_play(e,0);
    auto events=renderEvents(e,64);auto host=hostEvents(events);assert(host.size()==1&&host[0].e.hostMap==0x51&&host[0].e.target==3);
    for(auto&event:events)if(event.e.type!=ST_EVENT_HOST_PARAMETER)assert(event.e.hostMap==0);
    assert(hostEvents(renderEvents(e,64)).empty());
    st_engine_begin_update(e);st_engine_set_host_automation_map(e,0x52);st_engine_commit_update(e);
    host=hostEvents(renderEvents(e,64));assert(host.size()==1&&host[0].e.hostMap==0x52&&host[0].e.target==3&&host[0].e.value==0.25);
    st_engine_begin_update(e);st_engine_clear_project(e);st_engine_set_track_count(e,2);st_engine_add_host_automation_point(e,0,3,7,1,0,0.5);st_engine_commit_update(e);
    host=hostEvents(renderEvents(e,64));assert(host.size()==1&&host[0].e.hostMap==0);
}
