    constexpr uint64_t address=0xfedcba9876543210ULL;
    {Engine e;configure(e);st_engine_begin_update(e);st_engine_set_host_mixing(e,1,0);st_engine_add_host_automation_point(e,0,511,address,1,1,13.75);st_engine_add_host_automation_point(e,0,511,address,1,0,-12.25);st_engine_add_host_automation_point(e,0,511,address,1,1.0625,-3.125);st_engine_add_host_automation_point(e,0,ST_MAX_HOST_DESTINATIONS,1,1,0,99);st_engine_add_host_automation_point(e,0,-1,1,1,0,99);st_engine_add_host_automation_point(e,0,1,1,1,NAN,99);st_engine_add_host_automation_point(e,0,1,1,1,0,INFINITY);st_engine_commit_update(e);st_engine_play(e,0);auto events=hostEvents(renderEvents(e,7000,127));assert(events.size()==3);for(auto&event:events)assert(event.e.target==511&&event.e.track==-1&&event.e.address==address);assert(events[0].frame==0&&events[0].e.value==-12.25&&events[1].frame==6000&&events[1].e.value==13.75&&events[2].frame==6375&&events[2].e.value==-3.125);assert(hostEvents(renderEvents(e,128)).empty());st_engine_seek(e,0,1,0);events=hostEvents(renderEvents(e,1));assert(events.size()==1&&events[0].frame==0&&events[0].e.value==13.75);st_engine_refresh_automation(e);events=hostEvents(renderEvents(e,1));assert(events.size()==1&&events[0].frame==0);st_engine_begin_update(e);st_engine_clear_automation(e,0);st_engine_commit_update(e);assert(hostEvents(renderEvents(e,1)).empty());}
    // Raw doubles retain precision and linear timing; host destinations do not act
