    {Engine a,b;configure(a);configure(b);st_engine_begin_update(b);st_engine_add_host_automation_point(b,0,0,address,1,0,0);st_engine_add_host_automation_point(b,0,1,address,1,0,1);st_engine_commit_update(b);for(auto*e:{a.e,b.e}){st_engine_play(e,0);st_engine_note_on(e,0,0,69,100);}Audio x(1024),y(1024);render(a,x);render(b,y);assert(x.l==y.l&&x.r==y.r);}
    {Engine e;configure(e);st_engine_begin_update(e);st_engine_add_host_automation_point(e,0,0,0,0,0,-1e308);st_engine_add_host_automation_point(e,0,0,0,0,1,1e308);st_engine_commit_update(e);st_engine_play(e,0);auto events=hostEvents(renderEvents(e,6100));for(auto&event:events)assert(std::isfinite(event.e.value));}
