static void testMappedPublicationBounds(){Engine e;configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);installTestTiming(e);char error[128];assert(st_engine_commit_update_checked(e,error,sizeof error));double duration=st_engine_duration(e,1);st_engine_begin_update(e);assert(st_engine_set_pattern_timing_origin(e,1000000));assert(!st_engine_commit_update_checked(e,error,sizeof error)&&error[0]);assert(st_engine_duration(e,1)==duration);st_engine_cancel_update(e);st_engine_begin_update(e);st_engine_add_audio_clip(e,0,0,999999,2,0,1,0,0,0);assert(!st_engine_commit_update_checked(e,error,sizeof error)&&error[0]);st_engine_cancel_update(e);st_engine_begin_update(e);st_engine_add_audio_clip(e,0,0,999999,0,0,1,0,0,0);assert(st_engine_commit_update_checked(e,error,sizeof error));double pendingDuration=st_engine_duration(e,1);std::vector<float>tooLong(96000,.1f);assert(!st_engine_set_audio_asset(e,0,tooLong.data(),nullptr,tooLong.size(),48000));assert(st_engine_duration(e,1)==pendingDuration);st_engine_cancel_update(e);st_engine_begin_update(e);st_engine_clear_audio_clips(e);assert(st_engine_commit_update_checked(e,error,sizeof error));st_engine_play(e,1);Audio a(32);render(e,a);assert(st_engine_status(e).timingRevision==17);}

// Pattern loop range: rows 0..15 each carry note 60+row; one row is 6000 frames at 120 BPM, 4 LPB.
static void configureLoopMusic(STEngine*e,float swing=0){configure(e,ST_INSTRUMENT_AU);st_engine_begin_update(e);st_engine_set_timing(e,120,4,swing,.7f);st_engine_set_pattern(e,0,16);for(int r=0;r<16;++r){auto step=st_default_step();step.note=60+r;step.gate=.5f;st_engine_set_step(e,0,0,r,step,nullptr,0);}int32_t sequence[]={0};st_engine_set_sequence(e,sequence,1,0,0);st_engine_commit_update(e);}
static std::vector<Timed> noteOns(STEngine*e,size_t frames){std::vector<Timed>on;for(auto&v:renderEvents(e,frames))if(v.e.type==ST_EVENT_NOTE_ON)on.push_back(v);return on;}
static void assertNotes(const std::vector<Timed>&on,std::initializer_list<std::pair<uint64_t,int>> expected){assert(on.size()>=expected.size());size_t n=0;for(auto [frame,note]:expected){assert(on[n].frame==frame);assert(on[n].e.note==note);++n;}}
static void testPatternLoopRange(){
    // No range: unchanged pattern playback and wrap.
    {Engine e;configureLoopMusic(e);st_engine_play(e,0);auto on=noteOns(e,20*6000);assert(on.size()==20);for(size_t i=0;i<on.size();++i){assert(on[i].frame==i*6000);assert(on[i].e.note==60+int(i%16));}}
    // Range before Play: a cursor outside starts at the first loop row and wraps exactly at row boundaries.
    {Engine e;configureLoopMusic(e);st_engine_set_pattern_loop(e,4,7);st_engine_play(e,0);auto on=noteOns(e,12*6000);assert(on.size()==12);for(size_t i=0;i<on.size();++i){assert(on[i].frame==i*6000);assert(on[i].e.note==64+int(i%4));}auto status=st_engine_status(e);assert(status.playing&&status.row>=4&&status.row<=7);
        // Stop and Play keep the range; a seek inside the range starts there.
        st_engine_stop(e);st_engine_seek(e,0,6,0);st_engine_play(e,0);on=noteOns(e,4*6000);assertNotes(on,{{0,66},{6000,67},{12000,64},{18000,65}});
        // Clearing resumes normal progression from the current row.
        st_engine_set_pattern_loop(e,-1,-1);on=noteOns(e,4*6000);assertNotes(on,{{0,66},{6000,67},{12000,68},{18000,69}});}
    // Set while playing past the range: wraps at the next row boundary, not at the pattern end.
    {Engine e;configureLoopMusic(e);st_engine_play(e,0);auto on=noteOns(e,9*6000+100);assert(on.size()==10&&on.back().e.note==69);st_engine_set_pattern_loop(e,2,3);on=noteOns(e,4*6000);assertNotes(on,{{6000-100,62},{12000-100,63},{18000-100,62}});}
    // End row is clamped to the pattern length; one-row loops repeat that row.
    {Engine e;configureLoopMusic(e);st_engine_set_pattern_loop(e,14,40);st_engine_play(e,0);assertNotes(noteOns(e,4*6000),{{0,74},{6000,75},{12000,74},{18000,75}});}
    {Engine e;configureLoopMusic(e);st_engine_set_pattern_loop(e,9,9);st_engine_play(e,0);assertNotes(noteOns(e,3*6000),{{0,69},{6000,69},{12000,69}});}
    // A start row beyond the pattern disables the range.
    {Engine e;configureLoopMusic(e);st_engine_set_pattern_loop(e,20,30);st_engine_play(e,0);assertNotes(noteOns(e,3*6000),{{0,60},{6000,61},{12000,62}});}
    // Song mode ignores the range.
    {Engine e;configureLoopMusic(e);st_engine_set_pattern_loop(e,4,7);st_engine_play(e,1);auto on=noteOns(e,16*6000);assert(on.size()==16);for(size_t i=0;i<on.size();++i){assert(on[i].frame==i*6000&&on[i].e.note==60+int(i));}}
    // Swing keeps per-row lengths: odd rows 4500 frames, even rows 7500.
    {Engine e;configureLoopMusic(e,.25f);st_engine_set_pattern_loop(e,1,2);st_engine_play(e,0);assertNotes(noteOns(e,24000),{{0,61},{4500,62},{12000,61},{16500,62}});}
    // Mapped timing: the loop is the clock's loop domain and musical beats stay continuous for scheduling.
    {Engine e;configureLoopMusic(e);st_engine_begin_update(e);STClockTempoEvent tempos[]={{0,120}};STClockMeterEvent meters[]={{0,4,4}};char error[256];assert(st_engine_set_timing_map(e,tempos,1,meters,1,5,error,sizeof error));assert(st_engine_commit_update_checked(e,error,sizeof error));
        st_engine_set_pattern_loop(e,4,7);st_engine_play(e,0);auto on=noteOns(e,12*6000);assert(on.size()==12);for(size_t i=0;i<on.size();++i){assert(std::abs(int64_t(on[i].frame)-int64_t(i*6000))<=1);assert(on[i].e.note==64+int(i%4));}
        noteOns(e,1000);auto status=st_engine_status(e);assert(status.row==4&&status.beat>=1&&status.beat<1.1);
        STClockSpan span{};Audio a(512);realtime=true;st_engine_render_bus(e,0,0,a.l.data(),a.r.data(),512);realtime=false;assert(st_engine_clock_span(e,100,64,0,&span)==ST_CLOCK_OK);assert(span.context.flags&ST_CLOCK_LOOPING);assert(std::abs(span.context.loopStartBeat-1)<1e-9&&std::abs(span.context.loopEndBeat-2)<1e-9);}
}

// Queued jumps: pattern 0 = 16 rows (notes 60+row), pattern 1 = 4 rows (notes 80+row); 6000 frames per row.
static void configureQueueMusic(STEngine*e,std::initializer_list<int32_t> order){configureLoopMusic(e);st_engine_begin_update(e);st_engine_set_pattern(e,1,4);for(int r=0;r<4;++r){auto step=st_default_step();step.note=80+r;step.gate=.5f;st_engine_set_step(e,1,0,r,step,nullptr,0);}std::vector<int32_t>sequence(order);st_engine_set_sequence(e,sequence.data(),int32_t(sequence.size()),0,0);st_engine_commit_update(e);}
static void testQueuedJumps(){
    // Pattern mode: queued mid-pattern, honoured exactly at the pattern end; the new pattern then loops.
    {Engine e;configureQueueMusic(e,{0});st_engine_play(e,0);auto on=noteOns(e,3*6000+100);assert(on.size()==4);st_engine_queue_jump(e,1,-1);on=noteOns(e,100);auto status=st_engine_status(e);assert(status.queuedPattern==1&&status.queuedSequence==-1&&status.pattern==0);
        on=noteOns(e,18*6000);assert(on.size()==18);for(size_t i=0;i<12;++i)assert(on[i].e.note==64+int(i));for(size_t i=12;i<18;++i){assert(on[i].e.note==80+int((i-12)%4));assert(on[i].frame+16*6000-on[12].frame==16*6000+(i-12)*6000);}
        assert(on[12].frame==16*6000-(3*6000+200));status=st_engine_status(e);assert(status.pattern==1&&status.queuedPattern==-1);}
    // A later queue replaces the target; both <0 clears; Stop clears; stopped queues are ignored.
    {Engine e;configureQueueMusic(e,{0});st_engine_play(e,0);noteOns(e,1000);st_engine_queue_jump(e,1,-1);st_engine_queue_jump(e,-1,-1);auto on=noteOns(e,17*6000);assert(on.size()==17&&on[15].e.note==60);assert(st_engine_status(e).queuedPattern==-1);
        st_engine_queue_jump(e,1,-1);noteOns(e,100);assert(st_engine_status(e).queuedPattern==1);st_engine_stop(e);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);st_engine_queue_jump(e,1,-1);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);
        st_engine_play(e,0);noteOns(e,100);st_engine_queue_jump(e,1,-1);st_engine_seek(e,0,0,0);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);}
    // Pattern loop range: the jump happens at the end of the range instead of wrapping.
    {Engine e;configureQueueMusic(e,{0});st_engine_set_pattern_loop(e,4,7);st_engine_play(e,0);noteOns(e,100);st_engine_queue_jump(e,1,-1);auto on=noteOns(e,6*6000);assertNotes(on,{{6000-100,65},{12000-100,66},{18000-100,67},{24000-100,80},{30000-100,81}});}
    // Song mode: jump by sequence index at the end of the current block; then playback continues from there.
    {Engine e;configureQueueMusic(e,{0,1,0,1});st_engine_play(e,1);noteOns(e,6000);st_engine_queue_jump(e,-1,2);noteOns(e,100);auto status=st_engine_status(e);assert(status.queuedSequence==2&&status.queuedPattern==0);
        auto on=noteOns(e,32*6000);assert(on[14].e.note==60&&on[14].frame==16*6000-6100);status=st_engine_status(e);assert(status.sequence==3&&status.pattern==1&&status.queuedSequence==-1);
        for(size_t i=14;i<30;++i)assert(on[i].e.note==60+int(i-14));assert(on[30].e.note==80&&on[30].frame==on[14].frame+16*6000);}
    // Song mode by pattern: first occurrence; a natural end of the song is replaced by the jump.
    {Engine e;configureQueueMusic(e,{1,0});st_engine_play(e,1);noteOns(e,100);st_engine_queue_jump(e,0,-1);noteOns(e,100);assert(st_engine_status(e).queuedSequence==1);st_engine_queue_jump(e,-1,-1);
        noteOns(e,4*6000);st_engine_queue_jump(e,1,-1);noteOns(e,100);assert(st_engine_status(e).queuedSequence==0);auto on=noteOns(e,16*6000);assert(on.back().e.note==80&&st_engine_status(e).sequence==0&&st_engine_status(e).playing);}
    // Mode switch, Song to Pattern: the current block's pattern keeps looping from its end instead of advancing.
    {Engine e;configureQueueMusic(e,{0,1});st_engine_play(e,1);noteOns(e,3*6000+100);st_engine_queue_mode(e,0,0,-1);noteOns(e,100);auto status=st_engine_status(e);assert(status.queuedPattern==0&&status.songMode==1);
        auto on=noteOns(e,18*6000);assert(on.size()==18);for(size_t i=0;i<12;++i)assert(on[i].e.note==64+int(i));for(size_t i=12;i<18;++i)assert(on[i].e.note==60+int(i-12));
        assert(on[12].frame==16*6000-(3*6000+200));status=st_engine_status(e);assert(status.songMode==0&&status.pattern==0&&status.queuedPattern==-1&&status.playing);}
    // Mode switch, Pattern to Song: at the pattern end the song continues at the given block, then ends normally.
    {Engine e;configureQueueMusic(e,{1,0,1});st_engine_play(e,0);noteOns(e,6000);st_engine_queue_mode(e,1,-1,2);noteOns(e,100);auto status=st_engine_status(e);assert(status.queuedSequence==2&&status.queuedPattern==1&&status.songMode==0);
        auto on=noteOns(e,19*6000);assert(on[14].e.note==80&&on[14].frame==16*6000-6100);status=st_engine_status(e);assert(status.songMode==1&&status.sequence==2&&status.pattern==1);
        for(size_t i=14;i<18;++i)assert(on[i].e.note==80+int(i-14));}
    // A matching mode, a stopped engine or an invalid target queues nothing; Stop clears a pending switch.
    {Engine e;configureQueueMusic(e,{0,1});st_engine_play(e,1);noteOns(e,100);st_engine_queue_mode(e,1,-1,1);st_engine_queue_mode(e,0,-1,-1);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);
        st_engine_queue_mode(e,0,1,-1);noteOns(e,100);assert(st_engine_status(e).queuedPattern==1);st_engine_stop(e);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);
        st_engine_queue_mode(e,0,1,-1);noteOns(e,100);assert(st_engine_status(e).queuedPattern==-1);
        st_engine_play(e,1);noteOns(e,100);st_engine_queue_mode(e,0,1,-1);st_engine_queue_jump(e,-1,1);auto on=noteOns(e,17*6000);assert(st_engine_status(e).songMode==1&&st_engine_status(e).sequence==1);(void)on;}
    // Mapped timing: the jump is sample-accurate on the clock and keeps musical time continuous.
    {Engine e;configureQueueMusic(e,{0});st_engine_begin_update(e);STClockTempoEvent tempos[]={{0,120}};STClockMeterEvent meters[]={{0,4,4}};char error[256];assert(st_engine_set_timing_map(e,tempos,1,meters,1,9,error,sizeof error));assert(st_engine_commit_update_checked(e,error,sizeof error));
        st_engine_play(e,0);noteOns(e,6000);st_engine_queue_jump(e,1,-1);auto on=noteOns(e,17*6000);assert(on.size()==17);assert(on[14].e.note==75);assert(on[15].e.note==80&&std::abs(int64_t(on[15].frame)-int64_t(15*6000))<=1);assert(on[16].e.note==81&&std::abs(int64_t(on[16].frame)-int64_t(16*6000))<=1);assert(st_engine_status(e).pattern==1);}
    // Live voices keep sounding over a queued pattern change.
    {Engine e;configure(e);st_engine_begin_update(e);st_engine_set_pattern(e,0,2);st_engine_set_pattern(e,1,2);int32_t sequence[]={0};st_engine_set_sequence(e,sequence,1,0,0);st_engine_commit_update(e);st_engine_play(e,0);st_engine_note_on(e,0,0,69,100);Audio a(1000);render(e,a);st_engine_queue_jump(e,1,-1);Audio b(12000);render(e,b);assert(st_engine_status(e).pattern==1);assert(b.energy(11000,12000)>.001);}
}
static void testCountIn(){
    // 120 BPM 4/4: four clicks 24000 frames apart while stopped, then Play exactly one bar later.
    {Engine e;configureLoopMusic(e);st_engine_play_count_in(e,0,1);Audio a(96000);realtime=true;st_engine_render(e,a.l.data(),a.r.data(),96000);realtime=false;auto status=st_engine_status(e);assert(!status.playing&&status.countIn==1);
        for(int beat=0;beat<4;++beat){assert(a.energy(beat*24000,beat*24000+500)>1e-4);assert(a.energy(beat*24000+2000,beat*24000+23000)==0);}
        int crossingsA=0,crossingsB=0;for(int i=1;i<1400;++i){if(a.l[i-1]<=0&&a.l[i]>0)++crossingsA;if(a.l[24000+i-1]<=0&&a.l[24000+i]>0)++crossingsB;}assert(crossingsA>crossingsB);
        STEvent v;while(st_engine_pop_event(e,&v))assert(v.type!=ST_EVENT_NOTE_ON);
        auto on=noteOns(e,2*6000);assertNotes(on,{{0,60},{6000,61}});assert(st_engine_status(e).playing&&st_engine_status(e).countIn==0);}
    // Stop cancels; Play while playing ignores a count-in; metronome volume and meter set the clicks.
    {Engine e;configureLoopMusic(e);st_engine_play_count_in(e,0,1);noteOns(e,30000);assert(st_engine_status(e).countIn==3);st_engine_stop(e);auto on=noteOns(e,96000);assert(on.empty()&&st_engine_status(e).countIn==0&&!st_engine_status(e).playing);
        st_engine_begin_update(e);st_engine_set_metronome(e,0,3,8,.5f);st_engine_commit_update(e);st_engine_play_count_in(e,1,2);noteOns(e,100);assert(st_engine_status(e).countIn==6);on=noteOns(e,6*12000);assert(on.size()==1&&on[0].frame==6*12000-100);
        st_engine_play_count_in(e,0,1);noteOns(e,100);assert(st_engine_status(e).countIn==0&&st_engine_status(e).songMode);}
    // Live notes played during the count-in sound on after the downbeat.
    {Engine e;configure(e);st_engine_play_count_in(e,0,1);Audio a(1000);render(e,a);st_engine_note_on(e,0,0,69,100);Audio b(96000);render(e,b);assert(st_engine_status(e).playing);assert(b.energy(95500,96000)>.001);}
}
// Play/Stop are applied by the render thread. Between queueing and the next render (or indefinitely while the
// audio device is not rendering) the rendered status is stale; the control thread must see the requested
// transport: a stale "playing" after Stop turned the app's next Play press into another Stop.
static void testTransportStatusFollowsQueuedCommands(){
    auto playing=[](STEngine*e){auto s=st_engine_status(e);return st_status_transport_playing(&s)!=0;};
    auto countIn=[](STEngine*e){auto s=st_engine_status(e);return st_status_count_in(&s);};
    {Engine e;configure(e);Audio a(1000);st_engine_play(e,0);auto s=st_engine_status(e);assert(s.transportPending&&s.requestedPlaying&&!s.playing&&playing(e));
        render(e,a);s=st_engine_status(e);assert(s.playing&&!s.transportPending&&playing(e));
        st_engine_stop(e);s=st_engine_status(e);assert(s.playing&&s.transportPending&&!playing(e));// rendered is stale; requested is stopped
        // No render runs (device stopped): status stays stopped, and a later Play is reported as requested.
        for(int i=0;i<3;++i)assert(!playing(e));
        st_engine_play(e,0);assert(playing(e));st_engine_stop(e);assert(!playing(e));
        render(e,a);s=st_engine_status(e);assert(!s.playing&&!s.transportPending&&!playing(e));
        st_engine_play(e,0);render(e,a);assert(playing(e)&&!st_engine_status(e).transportPending);}
    // Count-in: a pending count-in is not playing and shows no stale count; Stop during it is immediate.
    {Engine e;configureLoopMusic(e);st_engine_play_count_in(e,0,1);assert(!playing(e)&&countIn(e)==0&&st_engine_status(e).transportPending);
        noteOns(e,30000);assert(!playing(e)&&countIn(e)==3&&!st_engine_status(e).transportPending);
        st_engine_stop(e);auto s=st_engine_status(e);assert(s.countIn==3&&s.transportPending&&!playing(e)&&countIn(e)==0);
        auto on=noteOns(e,96000);s=st_engine_status(e);assert(on.empty()&&!playing(e)&&s.countIn==0&&!s.transportPending);}
    // A queued jump left by the old playback is flagged stale (pending) once Stop is requested, and gone after it renders.
    {Engine e;configure(e);st_engine_begin_update(e);st_engine_set_pattern(e,0,2);st_engine_set_pattern(e,1,2);st_engine_commit_update(e);st_engine_play(e,0);Audio a(1000);render(e,a);
        st_engine_queue_jump(e,1,-1);render(e,a);assert(st_engine_status(e).queuedPattern==1);st_engine_stop(e);assert(!playing(e)&&st_engine_status(e).transportPending);
        render(e,a);auto s=st_engine_status(e);assert(!playing(e)&&s.queuedPattern==-1&&!s.transportPending);}
    // A capture/restore (export) flush publishes the applied serial with the transport state.
    {Engine e;configure(e);st_engine_play(e,0);Audio a(1000);render(e,a);st_engine_stop(e);auto state=st_engine_capture_transport(e);assert(!state.playing);auto s=st_engine_status(e);assert(!s.playing&&!s.transportPending);
        st_engine_play(e,0);state=st_engine_capture_transport(e);assert(state.playing&&!st_engine_status(e).transportPending&&st_engine_status(e).playing);}
}
static void testSeekStatusRevision(){
    Engine e;configure(e);Audio block(64);render(e,block);
    auto initial=st_engine_status(e);st_engine_seek(e,0,6,0);
    auto queued=st_engine_status(e);assert(queued.transportSeekRevision==initial.transportSeekRevision&&queued.row==initial.row);
    render(e,block);auto admitted=st_engine_status(e);assert(admitted.transportSeekRevision==initial.transportSeekRevision+1&&admitted.row==6);
    st_engine_play(e,0);render(e,block);st_engine_stop(e);render(e,block);
    assert(st_engine_status(e).transportSeekRevision==admitted.transportSeekRevision);
    st_engine_seek(e,0,2,0);render(e,block);auto back=st_engine_status(e);assert(back.transportSeekRevision==admitted.transportSeekRevision+1&&back.row==2);
    // The marker and row must remain one publication even with a concurrent status reader.
    std::atomic<bool> done{false};std::thread reader([&]{while(!done.load()){auto status=st_engine_status(e);if(status.transportSeekRevision>back.transportSeekRevision)assert(status.row==int((status.transportSeekRevision-back.transportSeekRevision)%2?5:2));}});
    for(int n=1;n<=2000;++n){st_engine_seek(e,0,n%2?5:2,0);render(e,block);}done=true;reader.join();
}
static void testModWheel(){
    auto energy=[](float wheel,bool panic=false){Engine e;configure(e);st_engine_begin_update(e);auto i=testToneInstrument(TEST_SAW);loadTestTone(e,0,TEST_SAW);i.attack=0;i.decay=0;i.sustain=1;i.volume=.5f;st_engine_set_instrument(e,0,i);st_engine_commit_update(e);if(wheel>0)st_engine_mod_wheel(e,0,wheel);st_engine_mod_wheel(e,1,1);if(panic)st_engine_panic(e);st_engine_note_on(e,0,0,93,100);Audio a(24000);render(e,a);return a.energy(12000,24000);};
    // Wheel up closes the filter; track 1's wheel does not affect track 0; panic resets it.
    double open=energy(0),closed=energy(1),reset=energy(1,true);assert(open>.001&&closed<open*.3&&std::abs(reset-open)<open*.01);
}
// Pad reorder: a host that released a moved plug-in's notes itself can end the old
// channel's external voices silently, so the channel's new occupant gets no stray
// release. Note events mark sequencer ownership in slot (1) versus live/preview (0).
static void testForgetExternalVoicesAndSequencedFlag(){
    {Engine e;configure(e,ST_INSTRUMENT_AU);st_engine_note_on(e,0,0,60,100);auto ev=noteEvents(renderEvents(e,64));assert(ev.size()==1&&ev[0].e.type==ST_EVENT_NOTE_ON&&ev[0].e.slot==0);
        assert(st_engine_forget_external_voices(e,-1)==0&&st_engine_forget_external_voices(e,st_channel_count(ST_MIN_RETURN_BUS))==0&&st_engine_forget_external_voices(e,1)==0);
        assert(st_engine_forget_external_voices(e,0)==1);st_engine_note_off(e,0,60);assert(noteEvents(renderEvents(e,256)).empty());
        st_engine_note_on(e,0,0,62,100);st_engine_note_off(e,0,62);ev=noteEvents(renderEvents(e,64));assert(ev.size()==2&&ev[1].e.type==ST_EVENT_NOTE_OFF&&ev[1].e.slot==0);}
    {Engine e;configure(e,ST_INSTRUMENT_AU);st_engine_begin_update(e);auto s=st_default_step();s.gate=.5f;st_engine_set_step(e,0,0,0,s,nullptr,0);st_engine_commit_update(e);st_engine_play(e,0);
        auto ev=noteEvents(renderEvents(e,6000));assert(ev.size()==2);for(auto&v:ev)assert(v.e.slot==1);}
}
// Note columns: each extra column of a track is its own lane on the track's channel (st_engine_set_step_column).
static STStep columnNote(int note,float gate=0){auto s=st_default_step();s.note=note;s.velocity=100;s.gate=gate;return s;}
static std::vector<std::pair<uint64_t,int>> columnEvents(STEngine*e,size_t frames,int type){std::vector<std::pair<uint64_t,int>>out;for(auto&v:noteEvents(renderEvents(e,frames)))if(v.e.type==type)out.push_back({v.frame,v.e.note});return out;}
static uint64_t offFrame(const std::vector<std::pair<uint64_t,int>>&offs,int note){for(auto&o:offs)if(o.second==note)return o.first;return UINT64_MAX;}
static void testNoteColumns(){
    // Two columns sustain together; a new note in column 1 releases only column 1; OFF in column 0 and CUT in column 1
    // end only their own column; a gated column-2 note stops after its gate while column 0's next note sounds on.
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);st_engine_set_pattern(e,0,16);int32_t seq[]={0};st_engine_set_sequence(e,seq,1,0,0);
        st_engine_set_step(e,0,0,0,columnNote(60),nullptr,0);st_engine_set_step_column(e,0,0,0,1,columnNote(64));
        st_engine_set_step_column(e,0,0,2,1,columnNote(67));st_engine_set_step(e,0,0,4,columnNote(-1),nullptr,0);st_engine_set_step_column(e,0,0,5,1,columnNote(-2));
        st_engine_set_step(e,0,0,6,columnNote(48),nullptr,0);st_engine_set_step_column(e,0,0,6,2,columnNote(72,1));st_engine_commit_update(e);st_engine_play(e,0);
        auto events=noteEvents(renderEvents(e,6000*9));std::vector<std::pair<uint64_t,int>>on,off;for(auto&v:events)(v.e.type==ST_EVENT_NOTE_ON?on:off).push_back({v.frame,v.e.note});
        assert(on.size()==5&&on[0].first==0&&on[1].first==0&&on[2]==std::make_pair(uint64_t(12000),67));
        assert(offFrame(off,64)==12000&&offFrame(off,60)==24000&&offFrame(off,67)==30000&&offFrame(off,72)==42000&&offFrame(off,48)==UINT64_MAX);
        for(auto&v:events)assert(v.e.track==0&&v.e.slot==1);}
    // Gate per column: column 0 gated one row, column 1 without a gate sounds on; a new column-0 note leaves column 1 alone.
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);st_engine_set_pattern(e,0,8);int32_t seq[]={0};st_engine_set_sequence(e,seq,1,0,0);
        st_engine_set_step(e,0,0,0,columnNote(60,1),nullptr,0);st_engine_set_step_column(e,0,0,0,1,columnNote(64));st_engine_set_step(e,0,0,2,columnNote(62),nullptr,0);st_engine_commit_update(e);st_engine_play(e,0);
        auto off=columnEvents(e,6000*4,ST_EVENT_NOTE_OFF);assert(offFrame(off,60)==6000&&offFrame(off,64)==UINT64_MAX&&offFrame(off,62)==UINT64_MAX);}
    // Row FX: column 0's ratchet and microtiming apply to the extra column's note; one probability roll drops the whole row.
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);st_engine_set_pattern(e,0,4);int32_t seq[]={0};st_engine_set_sequence(e,seq,1,0,0);
        auto s=columnNote(60);s.fx1={ST_FX_RATCHET,2};st_engine_set_step(e,0,0,0,s,nullptr,0);st_engine_set_step_column(e,0,0,0,1,columnNote(64));
        auto fxOnly=st_default_step();fxOnly.note=-3;fxOnly.fx1={ST_FX_MICROTIMING,.5f};st_engine_set_step(e,0,0,1,fxOnly,nullptr,0);st_engine_set_step_column(e,0,0,1,1,columnNote(65));
        auto drop=st_default_step();drop.note=-3;drop.fx1={ST_FX_PROBABILITY,0};st_engine_set_step(e,0,0,2,drop,nullptr,0);st_engine_set_step_column(e,0,0,2,1,columnNote(66));
        st_engine_commit_update(e);st_engine_play(e,0);auto on=columnEvents(e,6000*4,ST_EVENT_NOTE_ON);std::vector<uint64_t>hits64,hits65;int hits66=0;
        for(auto&o:on){if(o.second==64)hits64.push_back(o.first);if(o.second==65)hits65.push_back(o.first);hits66+=o.second==66;}
        assert((hits64==std::vector<uint64_t>{0,3000})&&(hits65==std::vector<uint64_t>{9000})&&hits66==0);}
    // A sampler track: two columns sound at once (more than three times the energy of one).
    {auto energy=[](bool two){Engine e;configure(e);st_engine_begin_update(e);st_engine_set_pattern(e,0,4);st_engine_set_step(e,0,0,0,columnNote(69),nullptr,0);if(two)st_engine_set_step_column(e,0,0,0,1,columnNote(69));st_engine_commit_update(e);st_engine_play(e,0);Audio a(4800);render(e,a);return a.energy(2400,4800);};
        double one=energy(false),both=energy(true);assert(one>.001&&both>one*3);}
    // Copy-on-write and resize: a reused pattern keeps its columns, a shortened pattern drops columns past its end,
    // clear_step clears every column, and the scheduler ignores columns of removed tracks.
    {Engine e;configure(e,ST_INSTRUMENT_MIDI);st_engine_begin_update(e);st_engine_set_pattern(e,0,8);int32_t seq[]={0};st_engine_set_sequence(e,seq,1,1,0);
        st_engine_set_step_column(e,0,0,0,1,columnNote(64));st_engine_set_step_column(e,0,0,1,3,columnNote(65));st_engine_set_step_column(e,0,0,6,7,columnNote(66));st_engine_set_step_column(e,0,1,0,1,columnNote(70));
        st_engine_set_step_column(e,0,0,2,8,columnNote(99));st_engine_set_step_column(e,0,0,2,-1,columnNote(99));st_engine_commit_update(e);
        st_engine_begin_update(e);st_engine_clear_project(e);st_engine_set_track_count(e,2);assert(st_engine_reuse_pattern(e,0));st_engine_set_sequence(e,seq,1,1,0);st_engine_commit_update(e);
        st_engine_play(e,0);auto on=columnEvents(e,6000*8,ST_EVENT_NOTE_ON);std::vector<int>notes;for(auto&o:on)notes.push_back(o.second);std::sort(notes.begin(),notes.end());assert((notes==std::vector<int>{64,65,66,70}));st_engine_stop(e);renderEvents(e,256);
        st_engine_begin_update(e);st_engine_set_pattern(e,0,4);st_engine_clear_step(e,0,0,1);st_engine_set_track_count(e,1);st_engine_commit_update(e);st_engine_play(e,0);
        on=columnEvents(e,6000*4,ST_EVENT_NOTE_ON);assert(on.size()==1&&on[0].second==64);}
}
